package org.zhbot.daeyalt_essence_mine;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class DaeyaltEssenceMineTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(DaeyaltEssenceMinePlugin.class);
		RuneLite.main(args);
	}
}

package org.zhbot.daeyalt_essence_mine;

import java.awt.Color;

import net.runelite.api.SoundEffectID;
import net.runelite.client.config.*;

@ConfigGroup(DaeyaltEssenceMineConfig.group)
public interface DaeyaltEssenceMineConfig extends Config
{
	String group = "daeyalt-essence-mine";

	@ConfigSection(
			name = "Notifications",
			description = "Configure notifications",
			position = 0
	)
	String notificationsSection = "notificationsSection";

	@ConfigItem(
			keyName = "notifications",
			name = "Client notification",
			description = "Trigger a client notification on daeyalt essence change",
			section = notificationsSection,
			position = 0
	)
	default Notification notification()
	{
		return Notification.ON;
	}

	@ConfigItem(
			keyName = "ingameSound",
			name = "In-game sound",
			description = "Play an in-game sound on daeyalt essence change",
			section = notificationsSection,
			position = 1
	)
	default boolean ingameSound()
	{
		return false;
	}

	@ConfigItem(
			keyName = "soundId",
			name = "Sound ID",
			description = "The in-game sound to play.\n3925 is the Grand Exchange offer chime; other easily-heard options are 2266 (UI beep), 3929 (plop) and 1930 (teleport woosh).",
			section = notificationsSection,
			position = 2
	)
	default int soundId()
	{
		return SoundEffectID.GE_ADD_OFFER_DINGALING;
	}

	@ConfigItem(
			keyName = "soundFollowGameVolume",
			name = "Follow game volume",
			description = "Use the in-game sound effect volume. If muted in-game, it will use the \"Volume\" setting.",
			section = notificationsSection,
			position = 3
	)
	default boolean soundFollowGameVolume()
	{
		return true;
	}

	@ConfigItem(
			keyName = "soundVolume",
			name = "Volume",
			description = "Volume to play the sound effect at when not using game volume.",
			section = notificationsSection,
			position = 4
	)
	@Range(
			min = 1,
			max = 127
	)
	default int soundVolume()
	{
		return 127;
	}

	@ConfigSection(
			name = "Daeyalt Essence Overlays",
			description = "Configure overlays",
			position = 1
	)
	String daeyaltEssenceOverlaysSection = "daeyaltEssenceOverlaysSection";

	@ConfigItem(
			keyName = "showDaeyaltEssenceIndicator",
			name = "Show indicator",
			description = "Configures whether to display an indicator when daeyalt essence is ready to be mined",
			section = daeyaltEssenceOverlaysSection,
			position = 0
	)
	default boolean showDaeyaltEssenceIndicator()
	{
		return true;
	}

	@ConfigItem(
			keyName = "showDaeyaltEssenceTimer",
			name = "Show timer",
			description = "Configures whether to display a timer for when a daeyalt essence is about to despawn",
			section = daeyaltEssenceOverlaysSection,
			position = 1
	)
	default boolean showDaeyaltEssenceTimer()
	{
		return true;
	}

	@ConfigItem(
			keyName = "showDaeyaltEssenceClickbox",
			name = "Show click box",
			description = "Configures whether to display a click box when daeyalt essence is ready to be mined",
			section = daeyaltEssenceOverlaysSection,
			position = 2
	)
	default boolean showDaeyaltEssenceClickbox()
	{
		return true;
	}

	@ConfigItem(
			keyName = "showDaeyaltEssenceClickboxAvailable",
			name = "Available colour",
			description = "Configures Color of available daeyalt essence",
			section = daeyaltEssenceOverlaysSection,
			position = 3
	)
	default Color showDaeyaltEssenceClickboxAvailable()
	{
		return Color.GREEN;
	}
}

package org.zhbot.daeyalt_essence_mine;

import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.components.ProgressPieComponent;

import java.awt.*;

public class DaeyaltEssenceMineOverlay extends Overlay {
    private static final int Z_OFFSET = 200;

    private static final int MIN_DESPAWN_TICK = 92;
    private static final int MAX_DESPAWN_TICK = 110;

    private final Client client;
    private final DaeyaltEssenceMinePlugin plugin;
    private final DaeyaltEssenceMineConfig config;
    private final SkillIconManager skillIconManager;

    @Inject
    private DaeyaltEssenceMineOverlay(Client client, DaeyaltEssenceMinePlugin plugin, DaeyaltEssenceMineConfig config, SkillIconManager skillIconManager)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        this.skillIconManager = skillIconManager;

        setLayer(OverlayLayer.ABOVE_SCENE);
        setPosition(OverlayPosition.DYNAMIC);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (plugin.outsideDaeyaltEssenceMine())
            return null;

        var activeDaeyaltEssence = plugin.getActiveDaeyaltEssence();
        if (activeDaeyaltEssence == null)
            return null;

        if (config.showDaeyaltEssenceClickbox())
        {
            var clickbox = activeDaeyaltEssence.getClickbox();
            var mousePosition = client.getMouseCanvasPosition();
            OverlayUtil.renderHoverableArea(graphics, clickbox, mousePosition, plugin.getClickboxFillColorMinable(), plugin.getClickboxBorderColorMinable(), plugin.getClickboxBorderHoverColorMinable());
        }

        if (config.showDaeyaltEssenceIndicator())
        {
            var gameObjectLocation = activeDaeyaltEssence.getLocalLocation();
            OverlayUtil.renderImageLocation(client, graphics, gameObjectLocation, skillIconManager.getSkillImage(Skill.MINING, false), Z_OFFSET);
        }

        if (config.showDaeyaltEssenceTimer())
        {
            var spawnedTicks = client.getTickCount() - plugin.getActiveDaeyaltEssenceSpawnTick();
            var colour = spawnedTicks < MIN_DESPAWN_TICK ? new Color(0, 255, 0) : new Color(233, 213, 2);

            var pie = new ProgressPieComponent();
            pie.setPosition(activeDaeyaltEssence.getCanvasLocation(0));
            pie.setProgress(1.0d - spawnedTicks / (double)MAX_DESPAWN_TICK);
            pie.setBorderColor(colour.darker());
            pie.setFill(colour);
            pie.render(graphics);
        }

        return null;
    }
}

package org.zhbot.daeyalt_essence_mine;

import com.google.inject.Provides;
import java.awt.Color;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.ObjectID;
import net.runelite.client.Notifier;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.util.ColorUtil;

@Slf4j
@PluginDescriptor(
	name = "Daeyalt Essence Mine"
)
public class DaeyaltEssenceMinePlugin extends Plugin
{
	private static final int DAEYALT_ESSENCE_MINE_REGION_ID = 14744;

	@Inject
	private Client client;

	@Inject
	private DaeyaltEssenceMineConfig config;

	@Inject
	private Notifier notifier;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private DaeyaltEssenceMineOverlay mine;

	@Getter
	private GameObject activeDaeyaltEssence;
	@Getter
	private int activeDaeyaltEssenceSpawnTick = -1;

	@Getter
	private Color clickboxBorderColorMinable;
	@Getter
	private Color clickboxFillColorMinable;
	@Getter
	private Color clickboxBorderHoverColorMinable;

	private boolean inDaeyaltEssenceMine = false;

	@Override
	protected void startUp() throws Exception
	{
		overlayManager.add(mine);

		updateConfig();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (event.getGroup().equals(DaeyaltEssenceMineConfig.group))
			updateConfig();
	}

	private void updateConfig()
	{
		clickboxBorderColorMinable = config.showDaeyaltEssenceClickboxAvailable();
		clickboxFillColorMinable = ColorUtil.colorWithAlpha(clickboxBorderColorMinable, 50);
		clickboxBorderHoverColorMinable = clickboxBorderColorMinable.darker();
	}

	@Override
	protected void shutDown() throws Exception
	{
		overlayManager.remove(mine);

		activeDaeyaltEssence = null;
		activeDaeyaltEssenceSpawnTick = -1;

		clickboxFillColorMinable = null;
		clickboxBorderColorMinable = null;
		clickboxBorderHoverColorMinable = null;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		var gameState = event.getGameState();
		if (gameState != GameState.LOADING)
			return;

		activeDaeyaltEssence = null;
		activeDaeyaltEssenceSpawnTick = -1;
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		var obj = event.getGameObject();

		switch (obj.getId())
		{
			case ObjectID.DAEYALT_STONE_TOP_ACTIVE:
				if (obj == activeDaeyaltEssence)
					return;

				if (activeDaeyaltEssenceSpawnTick > 0)
				{
					notifier.notify(config.notification(), "Daeyalt Essence Mine spawned");

					if (config.ingameSound())
					{
						var volume = config.soundVolume();

						if (config.soundFollowGameVolume())
						{
							client.playSoundEffect(config.soundId(), volume);
						}
						else
						{
							var prefs = client.getPreferences();
							var prev = prefs.getSoundEffectVolume();
							prefs.setSoundEffectVolume(volume);
							client.playSoundEffect(config.soundId(), volume);
							prefs.setSoundEffectVolume(prev);
						}
					}
				}

				activeDaeyaltEssenceSpawnTick = client.getTickCount();
				activeDaeyaltEssence = obj;
				break;
			case ObjectID.DAEYALT_STONE_TOP:

				break;
		}
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		var object = event.getGameObject();
		if (object.getId() == ObjectID.DAEYALT_STONE_TOP_ACTIVE && object == activeDaeyaltEssence)
			activeDaeyaltEssence = null;
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		var player = client.getLocalPlayer();
		if (player == null)
		{
			inDaeyaltEssenceMine = false;
			return;
		}

		var worldLocation = player.getWorldLocation();
		if (worldLocation == null)
		{
			inDaeyaltEssenceMine = false;
			return;
		}

		var region = worldLocation.getRegionID();
		inDaeyaltEssenceMine = region == DAEYALT_ESSENCE_MINE_REGION_ID;

		if (!inDaeyaltEssenceMine)
		{
			activeDaeyaltEssence = null;
			activeDaeyaltEssenceSpawnTick = -1;
		}
	}

	@Provides
	DaeyaltEssenceMineConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(DaeyaltEssenceMineConfig.class);
	}

	public boolean outsideDaeyaltEssenceMine()
	{
		return !inDaeyaltEssenceMine;
	}
}
